import { Component } from '@angular/core';
import { SubHeroLogoComponent } from '../shared-ui/sub-hero-logo/sub-hero-logo.component';

@Component({
  selector: 'app-not-authorized',
  standalone: true,
  imports: [SubHeroLogoComponent],
  templateUrl: './not-authorized.component.html',
  styleUrls: ['./not-authorized.component.css']
})
export class NotAuthorizedComponent {

}
<section class="main-content">
  <div class="carousel">
    <div class="carousel-image"><img src="../../assets/images/hero-3.jpg" alt="pie being prepared" /></div>
  </div>

  <app-sub-hero-logo>
    <ng-container title>Oops! You are not authorized!</ng-container>
    <ng-container sub-title>Try logging in</ng-container>
  </app-sub-hero-logo>
</section>
